IF DB_ID(N'{{ConnectExportDatabaseName}}') IS NULL
BEGIN
    CREATE DATABASE [{{ConnectExportDatabaseName}}];
    PRINT 'Created database [{{ConnectExportDatabaseName}}].';
END
ELSE PRINT 'Database [{{ConnectExportDatabaseName}}] already exists.';

IF OBJECT_ID(N'[{{ConnectExportDatabaseName}}].[dbo].[{{RemoteTableName}}]') IS NULL
    SELECT TOP (0) * INTO [{{ConnectExportDatabaseName}}].[dbo].[{{RemoteTableName}}]
    FROM [{{ModelSourceDatabaseName}}].[dbo].[{{SourceTableName}}];IF NOT EXISTS (SELECT 1 FROM [{{ConnectExportDatabaseName}}].sys.key_constraints
               WHERE [type] = 'PK' AND parent_object_id = OBJECT_ID(N'[{{ConnectExportDatabaseName}}].[dbo].[{{RemoteTableName}}]'))
BEGIN
    ALTER TABLE [{{ConnectExportDatabaseName}}].[dbo].[{{RemoteTableName}}] ADD CONSTRAINT [PK_{{RemoteTableName}}] PRIMARY KEY ([{{ExportKeyColumn}}]);
    PRINT 'Added primary key ([{{ExportKeyColumn}}]) to [{{ConnectExportDatabaseName}}].[dbo].[{{RemoteTableName}}].';
END
ELSE PRINT '[{{ConnectExportDatabaseName}}].[dbo].[{{RemoteTableName}}] already has a primary key.';
